            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalString.read(buf),
        )
    }

    override fun allocationSize(value: PairingResult) = (
            FfiConverterByteArray.allocationSize(value.`pairingFile`) +
            FfiConverterOptionalString.allocationSize(value.`deviceName`) +
            FfiConverterOptionalString.allocationSize(value.`deviceModel`) +
            FfiConverterOptionalString.allocationSize(value.`deviceUdid`)
    )

