 */
public object FfiConverterTypeGsError : FfiConverterRustBuffer<GsException> {
    override fun read(buf: ByteBuffer): GsException {
        

        return when(buf.getInt()) {
            1 -> GsException.Message(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: GsException): ULong {
        return when(value) {
            is GsException.Message -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: GsException, buf: ByteBuffer) {
        when(value) {
            is GsException.Message -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Mirrors `plume_core::auth::LoginState` for the FFI boundary -- kept as a
 * separate type so the vendored upstream crate doesn't need uniffi derives.
 * `NeedsSmsVerification`'s `VerifyBody` payload is intentionally dropped here;
 * `GrandslamSession` remembers it internally and `verify_sms_2fa` reuses it,
 * so Kotlin only ever deals with plain state + a code string.
 */
sealed class GsLoginState {
    
    object LoggedIn : GsLoginState()
    
    
    object NeedsDevice2fa : GsLoginState()
    
    
    object Needs2faVerification : GsLoginState()
    
    
    object NeedsSms2fa : GsLoginState()
    
    
    object NeedsSmsVerification : GsLoginState()
    
    
    data class NeedsExtraStep(
        val `step`: kotlin.String) : GsLoginState() {
        companion object
    }
    
    object NeedsLogin : GsLoginState()
    
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeGsLoginState : FfiConverterRustBuffer<GsLoginState>{
    override fun read(buf: ByteBuffer): GsLoginState {
        return when(buf.getInt()) {
            1 -> GsLoginState.LoggedIn
            2 -> GsLoginState.NeedsDevice2fa
            3 -> GsLoginState.Needs2faVerification
            4 -> GsLoginState.NeedsSms2fa
            5 -> GsLoginState.NeedsSmsVerification
            6 -> GsLoginState.NeedsExtraStep(
                FfiConverterString.read(buf),
                )
            7 -> GsLoginState.NeedsLogin
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: GsLoginState) = when(value) {
        is GsLoginState.LoggedIn -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is GsLoginState.NeedsDevice2fa -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is GsLoginState.Needs2faVerification -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is GsLoginState.NeedsSms2fa -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is GsLoginState.NeedsSmsVerification -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is GsLoginState.NeedsExtraStep -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`step`)
            )
        }
        is GsLoginState.NeedsLogin -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: GsLoginState, buf: ByteBuffer) {
        when(value) {
            is GsLoginState.LoggedIn -> {
                buf.putInt(1)
                Unit
            }
            is GsLoginState.NeedsDevice2fa -> {
                buf.putInt(2)
                Unit
            }
            is GsLoginState.Needs2faVerification -> {
                buf.putInt(3)
                Unit
            }
            is GsLoginState.NeedsSms2fa -> {
                buf.putInt(4)
                Unit
            }
            is GsLoginState.NeedsSmsVerification -> {
                buf.putInt(5)
                Unit
            }
            is GsLoginState.NeedsExtraStep -> {
                buf.putInt(6)
                FfiConverterString.write(value.`step`, buf)
                Unit
            }
            is GsLoginState.NeedsLogin -> {
                buf.putInt(7)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







